mapper.select:
SELECT c.CLASS_IDX, c.PROVIDER_IDX, u.USER_NAME, c.TITLE, c.INTRO, c.MINOR_FIELD_IDX, c.MINOR_REGION_IDX, c.PRICE, c.PHOTO, c.VIDEO, c.START_DATE, c.END_DATE, c.CREATED_AT, c.MAX_USER_CNT, NVL(r.AVG_RATING, 0) AS AVG_RATING, NVL(r.REVIEW_CNT, 0) AS REVIEW_CNT FROM CLASS c LEFT JOIN MINOR_FIELD mf ON mf.MINOR_FIELD_IDX = c.MINOR_FIELD_IDX LEFT JOIN MINOR_REGION mr ON mr.MINOR_REGION_IDX = c.MINOR_REGION_IDX LEFT JOIN USERS u ON u.USER_IDX = c.PROVIDER_IDX LEFT JOIN ( SELECT CLASS_IDX, ROUND(AVG(RATING), 1) AS AVG_RATING, COUNT(*) AS REVIEW_CNT FROM REVIEW_CLASS GROUP BY CLASS_IDX ) r ON r.CLASS_IDX = c.CLASS_IDX
AND TRUNC(c.END_DATE) >= TRUNC(SYSDATE)
AND c.MINOR_FIELD_IDX = #{minorField}
AND mf.MAJOR_FIELD_IDX = #{majorField}
AND c.MINOR_REGION_IDX = #{minorRegion}
AND mr.MAJOR_REGION_IDX = #{majorRegion}
AND (c.TITLE LIKE '%' || #{q} || '%' OR c.INTRO LIKE '%' || #{q} || '%')
ORDER BY r.AVG_RATING DESC NULLS LAST, r.REVIEW_CNT DESC, c.CREATED_AT DESC
ORDER BY NVL(r.REVIEW_CNT, 0) DESC, c.CREATED_AT DESC
ORDER BY c.PRICE ASC NULLS LAST, c.CREATED_AT DESC
ORDER BY c.PRICE DESC NULLS LAST, c.CREATED_AT DESC
ORDER BY c.CREATED_AT DESC

SELECT COUNT(*)
FROM REVIEW_CLASS
WHERE CLASS_IDX =
#{class_idx}
AND REVIEWER_IDX = #{user_idx}
